          body: JSON.stringify({ name: input.value }),
        });
        projects.push(project);
        displayProjects();
        input.value = '';
        input.focus();
      } catch (error) {
        showError(error.message);
      } finally {
        submit.disabled = false;
      }
    });
    submit.disabled = true;
    try {
      projects = await api('/api/projects');
      displayProjects();
    } catch (error) {
      showError(error.message);
    } finally {
      submit.disabled = false;
